#include <stdio.h>

#define MAXN 200005
#define MAXM 200005

typedef long long ll;

int parent[MAXN];
ll size[MAXN];
int A[MAXM], B[MAXM];
ll ans[MAXM];

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

ll unite(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx == ry) return 0;
    ll pairs = (ll)size[rx] * size[ry];
    if (size[rx] < size[ry]) {
        parent[rx] = ry;
        size[ry] += size[rx];
    } else {
        parent[ry] = rx;
        size[rx] += size[ry];
    }
    return pairs;
}

