#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int u, v;
} Edge;

typedef struct {
    int *parent;
    int *size;
} DSU;

void dsu_init(DSU *dsu, int n) {
    dsu->parent = (int *)malloc((n + 1) * sizeof(int));
    dsu->size = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        dsu->parent[i] = i;
        dsu->size[i] = 1;
    }
}

int dsu_find(DSU *dsu, int x) {
    if (dsu->parent[x] == x) return x;
    dsu->parent[x] = dsu_find(dsu, dsu->parent[x]);
    return dsu->parent[x];
}

int dsu_unite(DSU *dsu, int a, int b, ll *decrease) {
    a = dsu_find(dsu, a);
    b = dsu_find(dsu, b);
    if (a == b) {
        *decrease = 0;
        return 0;
    }
    if (dsu->size[a] < dsu->size[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    *decrease = (ll)dsu->size[a] * (ll)dsu->size[b];
    dsu->parent[b] = a;
    dsu->size[a] += dsu->size[b];
    return 1;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Edge *edges = (Edge *)malloc(M * sizeof(Edge));
    for (int i = 0; i < M; i++) {
        scanf("%d %d", &edges[i].u, &edges[i].v);
    }

    ll *ans = (ll *)malloc(M * sizeof(ll));
    DSU dsu;
    dsu_init(&dsu, N);

    ll cur = (ll)N * (N - 1) / 2;
    for (int i = M - 1; i >= 0; i--) {
        ans[i] = cur;
        ll dec = 0;
        dsu_unite(&dsu, edges[i].u, edges[i].v, &dec);
        cur -= dec;
    }

    for (int i = 0; i < M; i++) {
        printf("%lld\n", ans[i]);
    }

    free(edges);
    free(ans);
    free(dsu.parent);
    free(dsu.size);
    return 0;
}

