class DSU {
public:
    vector<int> parent, size;
    long long pairs;

    DSU(int n) {
        parent.resize(n + 1);
        size.resize(n + 1, 1);
        pairs = 0;
        for (int i = 1; i <= n; i++) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        // new pairs formed = size[ra] * size[rb]
        pairs += 1LL * size[ra] * size[rb];
        if (size[ra] < size[rb]) swap(ra, rb);
        parent[rb] = ra;
        size[ra] += size[rb];
    }
};

