        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    static long unite(int x, int y) {
        int px = find(x);
        int py = find(y);
        if (px == py) return 0;
        // merge smaller into larger
        if (size[px] < size[py]) {
            int tmp = px; px = py; py = tmp;
        }
        parent[py] = px;
        long merged = (long) size[px] * size[py];
        size[px] += size[py];
        return merged;
    }

    public static void main(String[] args) throws IOException {
